import{_ as l,a0 as p,w as s,s as i,ao as d,I as n,x as e,a1 as r,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"增強邊緣計算的安全性 | LCTT x X-CMD","titleTemplate":false,"description":"增強邊緣計算的安全性 | LCTT (201904) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"增強邊緣計算的安全性 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"增強邊緣計算的安全性 | LCTT (201904) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201904/20190409 Enhanced security at the edge","title":"增強邊緣計算的安全性","tag":"201904","desc":""},"relativePath":"201904/20190409 Enhanced security at the edge.md","filePath":"[post].md"}'),u={name:"201904/20190409 Enhanced security at the edge.md"};function m(T,t,f,h,g,w){const a=p("Link");return s(),i("div",null,[t[15]||(t[15]=d('<h1 id="增強邊緣計算的安全性" tabindex="-1">增強邊緣計算的安全性 <a class="header-anchor" href="#增強邊緣計算的安全性" aria-label="Permalink to “增強邊緣計算的安全性”">​</a></h1><blockquote><p>邊緣計算環境帶來的安全風險迫使公司必須特別關注它的安全措施。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2019/04/istock-1091707448-100793312-large.jpg" alt=""></p><p>説數據安全是高管們和董事會最關注的問題已經是陳詞濫調了。但問題是：數據安全問題不會自己消失。</p><p>駭客和攻擊者一直在尋找利用缺陷的新方法。就像公司開始使用人工智能和機器學習等新興技術來自動化地保護他們的組織一樣，那些不良分子們也在使用這些技術來達成他們的目的。</p><p>簡而言之，安全問題是一定不能忽視的。現在，隨着越來越多的公司開始使用邊緣計算，如何保護這些邊緣計算環境，需要有新的安全考量。</p><h3 id="邊緣計算的風險更高" tabindex="-1">邊緣計算的風險更高 <a class="header-anchor" href="#邊緣計算的風險更高" aria-label="Permalink to “邊緣計算的風險更高”">​</a></h3><p>正如 Network World 的一篇文章所説，邊緣計算的安全架構應該將重點放在物理安全上。這並不是説要忽視保護傳輸過程中的數據。而是説，實際的物理環境和物理設備更加值得關注。</p><p>例如，邊緣計算的硬件設備通常位於較大的公司或者廣闊空間中，有時候是在很容易進入的共享辦公室和公共區域裏。從表面上看，這節省了成本，能更快地訪問到相關的數據，而不必在後端的數據中心和前端的設備之間往返。</p><p>但是，如果沒有任何級別的訪問控制，這台設備就會暴露在惡意操作和簡單人為錯誤的雙重風險之下。想像一下辦公室的清潔工意外地關掉了設備，以及隨之而來的停機所造成的後果。</p><p>另一個風險是 “影子邊緣 IT”。有時候非 IT 人員會部署一個邊緣設備來快速啓動項目，卻沒有及時通知 IT 部門這個設備正在連接到網絡。例如，零售商店可能會主動安裝他們自己的數字標牌，或者，銷售團隊會將物聯網傳感器應用到電視中，並在銷售演示中實時地部署它們。</p><p>在這種情況下，IT 部門很少甚至完全看不到這些邊緣設備，這就使得網絡可能暴露在外。</p><h3 id="保護邊緣計算環境" tabindex="-1">保護邊緣計算環境 <a class="header-anchor" href="#保護邊緣計算環境" aria-label="Permalink to “保護邊緣計算環境”">​</a></h3><p>部署微型數據中心（MDC）是規避上述風險的一個簡單方法。</p><blockquote><p>“在歷史上，大多數這些[邊緣]環境都是不受控制的，”施耐德電氣安全能源部門的首席技術官和創新高級副總裁 Kevin Brown 説。“它們可能是第 1 級，但很可能是第 0 級類型的設計 —— 它們就像開放的配線櫃。它們現在需要像微型數據中心一樣的對待。你管理它需要像管理關鍵任務數據中心一樣”</p></blockquote><p>單説聽起來的感覺，這個解決方案是一個安全、獨立的機箱，它包括在室內和室外運行程序所需的所有存儲空間、處理性能和網絡資源。它同樣包含必要的電源、冷卻、安全和管理工具。</p><p>而它最重要的是高級別的安全性。這個裝置是封閉的，有上鎖的門，可以防止非法入侵。通過合適的供應商，DMC 可以進行定製，包括用於遠程數字化管理的監控攝像頭、傳感器和監控技術。</p><p>隨着越來越多的公司開始利用邊緣計算的優勢，他們必須利用安全解決方案的優勢來保護他們的數據和邊緣環境。</p><p>在 APC.com 上了解保護你的邊緣計算環境的最佳方案。</p><hr>',20)),n("p",null,[t[1]||(t[1]=e("via: ",-1)),r(a,{href:"https://www.networkworld.com/article/3388130/enhanced-security-at-the-edge.html"},{default:o(()=>[...t[0]||(t[0]=[e("https://www.networkworld.com/article/3388130/enhanced-security-at-the-edge.html",-1)])]),_:1})]),n("p",null,[t[6]||(t[6]=e("作者：",-1)),r(a,{href:"https://www.networkworld.com/author/Anne-Taylor/"},{default:o(()=>[...t[2]||(t[2]=[e("Anne Taylor",-1)])]),_:1}),t[7]||(t[7]=e(" 選題：",-1)),r(a,{href:"https://github.com/lujun9972"},{default:o(()=>[...t[3]||(t[3]=[e("lujun9972",-1)])]),_:1}),t[8]||(t[8]=e(" 譯者：",-1)),r(a,{href:"https://github.com/hopefully2333"},{default:o(()=>[...t[4]||(t[4]=[e("hopefully2333",-1)])]),_:1}),t[9]||(t[9]=e(" 校對：",-1)),r(a,{href:"https://github.com/wxy"},{default:o(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),n("p",null,[t[12]||(t[12]=e("本文由 ",-1)),r(a,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原創編譯，",-1)),r(a,{href:"https://linux.cn/"},{default:o(()=>[...t[11]||(t[11]=[e("Linux中國",-1)])]),_:1}),t[14]||(t[14]=e(" 榮譽推出",-1))])])}const b=l(u,[["render",m]]);export{x as __pageData,b as default};
